// Energy and CO2 figures (task 110), generated by scripts/build-energy.mjs from the original Global Carbon
// Project and Ember files in data/raw/energy/. Values exactly as published.
import data from '../data/energy/index.json';

export type Series = [number, number][];
export type EnergyKey = 'co2' | 'co2pc' | 'gen' | 'ren' | 'renShare' | 'ws' | 'wsShare' | 'fossilShare' | 'hydroShare' | 'otherRenShare';
type Entity = { iso3: string; sourceName: string; emberName?: string; region: string | null; series: Partial<Record<EnergyKey, Series>> };

export const energyMeta = (data as any).meta as {
  gcb: { name: string; version: string; file: string; published: string; doi: string; url: string; licence: string; licenceUrl: string; budget: string };
  ember: { name: string; url: string; file: string; licence: string; licenceUrl: string };
  downloaded: string;
};
const countries = (data as any).countries as Record<string, Entity>;
export const worldEnergy = (data as any).world as { series: Partial<Record<EnergyKey, Series>> };

export const valueIn = (s: Series | undefined, y: number) => s?.find(([x]) => x === y)?.[1] ?? null;
export const energyOf = (iso3: string) => countries[iso3];
export const allEnergy = () => Object.values(countries);

/** Year a ranking uses: the latest year in which at least 90% of the countries or areas that have the series
 * report a value (Ember publishes the newest year for only part of the world at first). */
export function energyYear(k: EnergyKey) {
  const counts = new Map<number, number>();
  for (const d of allEnergy()) for (const [y] of d.series[k] ?? []) counts.set(y, (counts.get(y) ?? 0) + 1);
  const max = Math.max(...counts.values());
  return Math.max(...[...counts].filter(([, n]) => n >= 0.9 * max).map(([y]) => y));
}

/** Countries or areas with a value for year y, largest first; rank = position among those. */
export function rankEnergy(k: EnergyKey, y: number) {
  return allEnergy()
    .map((d) => ({ iso3: d.iso3, region: d.region ?? 'Other', value: valueIn(d.series[k], y) }))
    .filter((d): d is { iso3: string; region: string; value: number } => d.value != null)
    .sort((a, b) => b.value - a.value || a.iso3.localeCompare(b.iso3)) // equal values: by ISO code
    .map((d, i) => ({ ...d, rank: i + 1 }));
}

/** Countries or areas that have the series but no value for year y, with their latest year. */
export function notRankedEnergy(k: EnergyKey, y: number) {
  return allEnergy()
    .filter((d) => d.series[k]?.length && valueIn(d.series[k], y) == null)
    .map((d) => ({ iso3: d.iso3, latestYear: d.series[k]!.at(-1)![0], latest: d.series[k]!.at(-1)![1] }));
}

/** Million tonnes of CO2 in words: "12.42 billion tonnes" / "573.0 million tonnes". */
export const tonnes = (mt: number) => (mt >= 1000 ? `${(mt / 1000).toFixed(2)} billion tonnes` : `${mt.toFixed(1)} million tonnes`);
/** Terawatt-hours: 1 decimal. */
export const twh = (v: number) => `${v.toLocaleString('en-US', { minimumFractionDigits: 1, maximumFractionDigits: 1 })} TWh`;
